# Helper to generate consistent embedding text for skills
def _embed(name, cat, stage, priority, desc, prereqs="", topics="", roles=""):
    lines = [f"Skill: {name}", f"Category: {cat}", f"Stage: {stage}", f"Priority: {priority}", f"Description: {desc}"]
    if prereqs: lines.append(f"Prerequisites: {prereqs}")
    if topics: lines.append(f"Topics: {topics}")
    if roles: lines.append(f"Applicable Roles: {roles}")
    return "\n".join(lines)


